begin;
create extension if not exists pgtap with schema extensions;
select plan(19);
insert into auth.users(id,email) values('b1000000-0000-4000-8000-000000000001','billing-one@example.test'),('b1000000-0000-4000-8000-000000000002','billing-two@example.test');
set local role service_role;
select ok(not has_table_privilege('authenticated','public.billing_customers','INSERT'),'customers cannot be forged');
select ok(not has_table_privilege('authenticated','public.billing_events','INSERT'),'events cannot be forged');
select ok(not has_function_privilege('authenticated','public.apply_billing_event(text,uuid,uuid,text,public.subscription_status,timestamptz,timestamptz,boolean)','EXECUTE'),'grants are service only');
select ok(not has_function_privilege('authenticated','public.reserve_provider_usage(uuid,text,integer,text)','EXECUTE'),'usage is service only');
select ok((select bool_and(relrowsecurity) from pg_class where oid in ('public.billing_customers'::regclass,'public.billing_events'::regclass,'public.billing_locks'::regclass)),'all private tables enable RLS');
insert into billing_customers(user_id,customer_id) values('b1000000-0000-4000-8000-000000000001','cus_owned');
select throws_ok($$insert into billing_customers(user_id,customer_id) values('b1000000-0000-4000-8000-000000000002','cus_owned')$$,'23505',null,'customer cannot belong to two users');
select ok(acquire_billing_lock('b1000000-0000-4000-8000-000000000001','b2000000-0000-4000-8000-000000000001'),'first operation holds lease');
select ok(not acquire_billing_lock('b1000000-0000-4000-8000-000000000001','b2000000-0000-4000-8000-000000000002'),'concurrent operation rejected');
select ok(apply_billing_event('evt_first','b1000000-0000-4000-8000-000000000001','b2000000-0000-4000-8000-000000000001','sub_fixture','active',now(),now()+interval '1 month',true),'verified subscription applied');
select ok(not apply_billing_event('evt_first','b1000000-0000-4000-8000-000000000001','b2000000-0000-4000-8000-000000000001','sub_fixture','expired',now(),now()+interval '1 month',false),'replay ignored');
select is((select status::text from subscriptions where user_id='b1000000-0000-4000-8000-000000000001' and is_current),'active','cancel-at-end still active');
select is((select value from plan_entitlements pe join entitlement_definitions e on e.id=pe.entitlement_definition_id join plans p on p.id=pe.plan_id where p.plan_key='premium' and e.entitlement_key='ads_enabled'),'false'::jsonb,'premium disables ads');
select ok(reserve_provider_usage('b1000000-0000-4000-8000-000000000001','premium_voice_calls',1,'test:reservation:one') is not null,'first reservation succeeds');
select ok(reserve_provider_usage('b1000000-0000-4000-8000-000000000001','premium_voice_calls',1,'test:reservation:two') is null,'pending counts toward allowance');
update usage_records set status='voided' where dedupe_key='test:reservation:one';
select ok(reserve_provider_usage('b1000000-0000-4000-8000-000000000001','premium_voice_calls',1,'test:reservation:three') is not null,'failed provider call releases allowance');
select ok(reserve_provider_usage('b1000000-0000-4000-8000-000000000002','premium_ai_calls',0,'test:reservation:four') is null,'zero limit enforced');
select ok(reserve_provider_usage('b1000000-0000-4000-8000-000000000002','premium_ai_calls',null,'test:reservation:five') is not null,'unconfigured allowance unlimited');
select is((select count(*)::int from learner_model_changes where user_id in ('b1000000-0000-4000-8000-000000000001','b1000000-0000-4000-8000-000000000002')),0,'commercial changes do not create learner changes');
delete from billing_locks;
insert into account_deletion_jobs(user_id) values('b1000000-0000-4000-8000-000000000001');
select ok(not acquire_billing_lock('b1000000-0000-4000-8000-000000000001','b2000000-0000-4000-8000-000000000001'),'deletion blocks new checkout');
select * from finish();
rollback;
